html:
{# Most Popular #}

{% if meta.preview == "true" %}
    <meta name="viewport" content="width=device-width, initial-scale=1">
{% endif %}

<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
<link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/slick-carousel@1.8.1/slick/slick.css"/>
<script src="https://cdn.jsdelivr.net/npm/slick-carousel@1.8.1/slick/slick.min.js"></script>

{# VARIABLES #}
{% set yougardenBlue = "#264f1c" %}
{% set yougardenBlueDark = "#1a3d14" %}
{% set yougardenDark = "#2c3e50" %}

{# MOST POPULAR badge defaults ON; FR toggle is fields.mostPopularBadge.active #}
{% set most_popular_off = fields.mostPopularBadge.active == false or fields.mostPopularBadge.active == 'false' or fields.mostPopularBadge.active == 0 or fields.mostPopularBadge.active == '0' %}
{% set show_most_popular = not most_popular_off %}

{# Overlay arrows default ON; FR toggle is fields.showArrows.active #}
{% set arrows_off = fields.showArrows.active == false or fields.showArrows.active == 'false' or fields.showArrows.active == 0 or fields.showArrows.active == '0' %}
{% set show_arrows = not arrows_off %}
{% set arrows_on_hover = fields.showArrows.onHover == true or fields.showArrows.onHover == 'true' or fields.showArrows.onHover == 1 or fields.showArrows.onHover == '1' %}
{% set sb_arrow_px = fields.overlayArrowSize if fields.overlayArrowSize else 36 %}
{% set cat_arrow_px = fields.categoryArrowSize if fields.categoryArrowSize else 36 %}

{% if fields.image.salesBadge == "yougarden" %}
    {% set salesBadgeColor = "#e3185d" %}
{% elif fields.image.salesBadge == "gardeningdirect" %}
    {% set salesBadgeColor = "#d00" %}
{% elif fields.image.salesBadge == "plantsmailshop" %}
    {% set salesBadgeColor = "#de6926" %}
{% elif fields.image.salesBadge == "roses.co.uk" %}
    {% set salesBadgeColor = "#f2eadd" %}
{% endif %}


<div class="{{safeid}} {{safeid}}__sb-wrapper">

    {# headline start #}
	{% if fields.headline.active %}

    <div class="{{safeid}}__headline-wrapper"{% if not fields.headline.linkUrl %} role="presentation" onclick="event.preventDefault(); event.stopPropagation(); return false;"{% endif %}>
		{% if fields.headline.linkUrl %}
			<a class="{{safeid}}__headline-link" href="{{ mergeField(fields.headline.linkUrl)|set_ga_tracking(
				utm_campaign=mergeField(fields.utmCampaign, {}),
				utm_medium=mergeField(fields.utmMedium, {}),
				utm_source=mergeField(fields.utmSource, {})) }}">
				<span class="{{safeid}}__headline-text">{{ mergeField(fields.headline.text) }}</span>
			</a>
		{% else %}
			<span class="{{safeid}}__headline-text">{{ mergeField(fields.headline.text) }}</span>
		{% endif %}
    </div>

{% endif %}
{# headline end #}

{# sub-headline start #}
{% if fields.subHeadline.active %}

    <div class="{{safeid}}__sub-headline" role="presentation" onclick="event.preventDefault(); event.stopPropagation(); return false;">
        {{ fields.subHeadline.text }}
    </div>

{% endif %}
{# sub-headline end #}

{% if fields.divider.active %}

    {% if fields.divider.active %}
        <div class="{{safeid}}__divider"></div>
    {% endif %}

{% endif %}

    {# products start #}

    <div class="{{safeid}}__slick">

        {% for row in products|batch(cols) %}
            {% for product in row %}
                {# product card start #}
                <div class="slick-slide imagecontainer">
                    <div class="custom-product-box {{safeid}}__custom-product-box">


                        {# product image start #}
                        {% if fields.image.active %}
                            <div class="{{safeid}}__product-image">
                                <a href="{{ mergeField(fields.redirectURL, { product: product })|set_ga_tracking(
                                    utm_campaign=mergeField(fields.utmCampaign, {}),
                                    utm_medium=mergeField(fields.utmMedium, {}),
                                    utm_source=mergeField(fields.utmSource, {})) }}">
                                    {# MOST POPULAR badge overlay - top left #}
                                    {% if show_most_popular %}
                                    <div class="{{safeid}}__most-popular-badge">MOST POPULAR</div>
                                    {% endif %}
                                    {% set saving = (product.ruv - product.uv) / product.ruv * 100 %}
                                    {% if saving > 0 %}
                                    <div class="{{ safeid }}__savings-badge"><div class="save"><span class="percentage">{{ saving|round(0) }}<span class="symbol">%</span></span><br>OFF</div></div>
                                    {% endif %}
                                    <img src="{{ product.img }}" loading="lazy" alt="{{ product.n }}">
                                </a>
                            </div>
                        {% endif %}
                        {# product image end #}

                        {# social proof start #}
                        {% if fields.socialProofMessaging.active  %}
                            <div class="{{safeid}}__social-proof">
                                {{ socialProof(product) }}
                            </div>
                        {% endif %}
                        {# social proof end #}

                        {# ratings start #}
                        {% if fields.ratingIcons.active %}
                            <div class="{{safeid}}__ratings">
                                {% if product|addProductRatings %}
                                    {{ product| addProductRatings }}
                                {% endif %}
                            </div>
                        {% endif %}
                        {# ratings end #}

                        {# product name start #}
                        {% if fields.productName.active  %}
                            <div class="{{safeid}}__product-name">
                                <a href="{{ mergeField(fields.redirectURL, { product: product })|set_ga_tracking(
                                    utm_campaign=mergeField(fields.utmCampaign, {}),
                                    utm_medium=mergeField(fields.utmMedium, {}),
                                    utm_source=mergeField(fields.utmSource, {})) }}">
                                    {{ product.n }}
                                </a>
                            </div>
                        {% endif %}
                        {# product name end #}

                        {# Fancy Centered Price Container #}
                        <div class="{{safeid}}__product-price-container-fancy">
                            {# product was price start #}
                            {% if fields.productWasPrice.active %}
                                <div class="{{safeid}}__product-was-price">
                                    {% if product.ruv and product.ruv > product.uv %}
                                         <span>{{ product.ruv|format_currency(product.curr, 2) }}</span>
                                    {% endif %}
                                </div>
                            {% endif %}
                            {# product was price end #}

                            {# product price start #}
                            {% if fields.productPrice.active %}
                                <div class="{{safeid}}__product-price-fancy">
                                    <a href="{{ mergeField(fields.redirectURL, { product: product })|set_ga_tracking(
                                        utm_campaign=mergeField(fields.utmCampaign, {}),
                                        utm_medium=mergeField(fields.utmMedium, {}),
                                        utm_source=mergeField(fields.utmSource, {})) }}" target="_blank">
                                        <span class="{{safeid}}__price-label">From</span>
                                        <span class="{{safeid}}__price-amount">{{ product.uv|format_currency(product.curr,2) }}</span>
                                    </a>
                                </div>
                            {% endif %}
                            {# product price end #}
                        </div>
                        {# product price end #}



                            {# cta start #}
                            {% if fields.callToAction.active %}
                                <a class="{{safeid}}__product-cta-button" href="{{ mergeField(fields.redirectURL, { product: product })|set_ga_tracking(
                                        utm_campaign=mergeField(fields.utmCampaign, {}),
                                        utm_medium=mergeField(fields.utmMedium, {}),
                                        utm_source=mergeField(fields.utmSource, {})) }}" target="_blank">
                                    {{ fields.callToAction.text }}
                                </a>
                            {% endif %}
                            {# cta end #}
                    </div>

                </div>
                {# product card end #}
            {% endfor %}
        {% endfor %}

    </div>
    {# products end #}

</div>

<link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/slick-carousel@1.8.1/slick/slick.css"/>
<style>
/* Category carousel: overlay chevrons on the tiles (same as taller MP smartblock). */
.frontpage .category-promotion-wrapper {
	margin-bottom: 0 !important;
	padding-bottom: 0 !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel {
	position: relative !important;
	overflow: visible !important;
	padding-bottom: 0 !important;
	margin-bottom: 0 !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-dots {
	display: none !important;
	visibility: hidden !important;
	height: 0 !important;
	margin: 0 !important;
	padding: 0 !important;
	overflow: hidden !important;
	pointer-events: none !important;
}
{% if show_arrows %}
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-prev,
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-next,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow {
	display: flex !important;
	align-items: center !important;
	justify-content: center !important;
	visibility: hidden !important;
	opacity: 0 !important;
	pointer-events: none !important;
	position: absolute !important;
	top: var(--yg-cat-arrow-top, 80px) !important;
	bottom: auto !important;
	transform: translateY(-50%) !important;
	width: {{ cat_arrow_px }}px !important;
	height: {{ cat_arrow_px }}px !important;
	margin: 0 !important;
	margin-left: 0 !important;
	margin-right: 0 !important;
	padding: 0 !important;
	border: 0 !important;
	border-radius: 4px !important;
	background: rgba(255, 255, 255, 0.94) !important;
	box-shadow: 0 1px 4px rgba(0, 0, 0, 0.14) !important;
	color: #264f1c !important;
	z-index: 6 !important;
	text-indent: 0 !important;
	font-size: 0 !important;
	line-height: 0 !important;
	cursor: pointer !important;
	transition: none !important;
	animation: none !important;
}
{% if arrows_on_hover %}
@media (hover: hover) and (pointer: fine) {
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-prev,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-next,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready .slick-arrow {
		visibility: visible !important;
		opacity: 0 !important;
		pointer-events: none !important;
		transition: opacity 0.15s ease !important;
	}
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready:hover > .slick-prev,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready:hover > .slick-next,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready:hover .slick-arrow {
		opacity: 1 !important;
		pointer-events: auto !important;
	}
}
@media (hover: none) {
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-prev,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-next,
	.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready .slick-arrow {
		visibility: visible !important;
		opacity: 1 !important;
		pointer-events: auto !important;
	}
}
{% else %}
.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-prev,
.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready > .slick-next,
.frontpage .category-promotion-wrapper .category-promotion-carousel.yg-cat-arrows-ready .slick-arrow {
	visibility: visible !important;
	opacity: 1 !important;
	pointer-events: auto !important;
	transition: none !important;
}
{% endif %}
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-prev,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-prev {
	left: 8px !important;
	right: auto !important;
	margin-left: 0 !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-next,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-next {
	right: 8px !important;
	left: auto !important;
	margin-right: 0 !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow:before,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow:after,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-prev:before,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-next:before,
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-prev:before,
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-next:before {
	display: none !important;
	content: none !important;
	font-size: 0 !important;
	width: 0 !important;
	height: 0 !important;
	opacity: 0 !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow svg {
	display: block !important;
	width: 33% !important;
	height: 44% !important;
	color: #264f1c !important;
	fill: currentColor !important;
}
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow svg + svg {
	display: none !important;
}
{% else %}
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-prev,
.frontpage .category-promotion-wrapper .category-promotion-carousel > .slick-next,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow:before,
.frontpage .category-promotion-wrapper .category-promotion-carousel .slick-arrow:after {
	display: none !important;
	visibility: hidden !important;
	opacity: 0 !important;
	pointer-events: none !important;
	width: 0 !important;
	height: 0 !important;
	font-size: 0 !important;
}
{% endif %}

    .{{safeid}}__slick {
        width: 100%;
        overflow: hidden;
        position: relative;
    }

    .{{safeid}}__slick .slick-slide {
        position: relative;
        box-sizing: border-box;
        height: auto;
        {% if fields.cardStyling.active %}
            background-color: {{ fields.cardStyling.backgroundColor }};
            border-radius: {{ fields.cardStyling.cornerStyle }};
            {% if fields.cardStyling.shadowtoggle %}
                box-shadow: 0px 0px 10px 0px;
            {% endif %}
            {% if fields.cardStyling.toggleBorder %}
                border: {{ fields.cardStyling.borderWidth }}px {{ fields.cardStyling.borderStyle }} {{ fields.cardStyling.borderColor }};
            {% endif %}
        {% endif %}
        align-items: unset;
    }

    .{{safeid}}__slick.slick-initialized .slick-slide, .slick-track {
        display: flex;
    }


    /* Overlay chevrons on the tiles — same treatment as category 8-up cards */
    {% if show_arrows %}
    .{{safeid}}__slick > .slick-arrow,
    .{{safeid}}__slick .slick-arrow {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
        position: absolute !important;
        top: var(--yg-home-arrow-top, 80px) !important;
        bottom: auto !important;
        transform: translateY(-50%) !important;
        width: {{ sb_arrow_px }}px !important;
        height: {{ sb_arrow_px }}px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 4px !important;
        background: rgba(255, 255, 255, 0.94) !important;
        box-shadow: 0 1px 4px rgba(0, 0, 0, 0.14) !important;
        color: #264f1c !important;
        z-index: 6 !important;
        text-indent: 0 !important;
        font-size: 0 !important;
        line-height: 0 !important;
        cursor: pointer !important;
        transition: none !important;
        animation: none !important;
    }

    {% if arrows_on_hover %}
    @media (hover: hover) and (pointer: fine) {
        .{{safeid}}__slick.yg-home-arrows-ready > .slick-arrow,
        .{{safeid}}__slick.yg-home-arrows-ready .slick-arrow {
            visibility: visible !important;
            opacity: 0 !important;
            pointer-events: none !important;
            transition: opacity 0.15s ease !important;
        }
        .{{safeid}}__slick.yg-home-arrows-ready:hover > .slick-arrow,
        .{{safeid}}__slick.yg-home-arrows-ready:hover .slick-arrow {
            opacity: 1 !important;
            pointer-events: auto !important;
        }
        .{{safeid}}__slick.yg-home-arrows-ready:hover .slick-arrow.slick-disabled {
            opacity: 0.35 !important;
        }
    }
    @media (hover: none) {
        .{{safeid}}__slick.yg-home-arrows-ready > .slick-arrow,
        .{{safeid}}__slick.yg-home-arrows-ready .slick-arrow {
            visibility: visible !important;
            opacity: 1 !important;
            pointer-events: auto !important;
        }
    }
    {% else %}
    .{{safeid}}__slick.yg-home-arrows-ready > .slick-arrow,
    .{{safeid}}__slick.yg-home-arrows-ready .slick-arrow {
        visibility: visible !important;
        opacity: 1 !important;
        pointer-events: auto !important;
        transition: none !important;
    }
    {% endif %}

    .{{safeid}}__slick > .slick-prev,
    .{{safeid}}__slick .slick-prev {
        left: 8px !important;
        right: auto !important;
    }

    .{{safeid}}__slick > .slick-next,
    .{{safeid}}__slick .slick-next {
        right: 8px !important;
        left: auto !important;
    }

    /* Match inset on both sides (card padding ~10px) so arrows sit equally on the image lips */
    @media (min-width: 701px) {
        .{{safeid}}__slick > .slick-prev,
        .{{safeid}}__slick .slick-prev {
            left: 18px !important;
        }
        .{{safeid}}__slick > .slick-next,
        .{{safeid}}__slick .slick-next {
            right: 18px !important;
        }
    }

    .{{safeid}}__slick .slick-arrow:before,
    .{{safeid}}__slick .slick-arrow:after,
    .{{safeid}}__slick .slick-prev:before,
    .{{safeid}}__slick .slick-next:before {
        display: none !important;
        content: none !important;
        font-size: 0 !important;
        width: 0 !important;
        height: 0 !important;
        opacity: 0 !important;
    }

    .{{safeid}}__slick .slick-arrow svg + svg {
        display: none !important;
    }

    .{{safeid}}__slick .slick-arrow svg {
        display: block !important;
        width: 33% !important;
        height: 44% !important;
        color: #264f1c !important;
        fill: currentColor !important;
    }

    .{{safeid}}__slick .slick-arrow.slick-disabled {
        opacity: 0.35 !important;
        cursor: default;
    }

    /* Slightly smaller overlay arrows on mobile cards */
    @media (max-width: 700px) {
        .{{safeid}}__slick > .slick-arrow,
        .{{safeid}}__slick .slick-arrow {
            width: 28px !important;
            height: 28px !important;
            border-radius: 4px !important;
        }
    }
    {% else %}
    .{{safeid}}__slick > .slick-arrow,
    .{{safeid}}__slick .slick-arrow,
    .{{safeid}}__slick .slick-prev,
    .{{safeid}}__slick .slick-next {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
        width: 0 !important;
        height: 0 !important;
    }
    {% endif %}

    /* slick dots styling */
    .{{safeid}}__slick .slick-dots {
        display: flex !important;
        justify-content: center;
        align-items: center;
        list-style: none;
        padding: 0;
        margin: 20px 0 0 0;
    }
    .{{safeid}}__slick .slick-dots li {
        display: inline-block;
        margin: 0 5px;
        padding: 0;
    }
    .{{safeid}}__slick .slick-dots li button {
        font-size: 0;
        line-height: 0;
        display: block;
        width: 12px;
        height: 12px;
        padding: 0;
        cursor: pointer;
        color: transparent;
        border: 0;
        outline: none;
        background: #ccc;
        border-radius: 50%;
        transition: background 0.3s;
    }
    .{{safeid}}__slick .slick-dots li button:hover,
    .{{safeid}}__slick .slick-dots li.slick-active button {
        background: #333;
    }
    .{{safeid}}__slick .slick-dots li button:before {
        display: none !important;
    }

    /* header styles */

	.{{safeid}}__sb-wrapper {
		display:flex;
		flex-direction: column;
		margin: 0 auto;
		background-color:{{ fields.backgroundColor or '#FFFFFF' }};
		position: relative;
		{% if fields.carouselActive  %}
			max-height: fit-content;
		{% endif %}
		{% if not fields.fillSmartBlockParentContainer %}
			max-width: {{ fields.width }}px;
		{% endif %}
		{% if fields.fillSmartBlockParentContainer == false %}
			width:  {{ fields.width }}px;
		{% endif %}
		{% if fields.borders.active %}
			border:{{ fields.borders.weight }}px solid {{ fields.borders.color or '#979797' }};
		{% endif %}
		{% if fields.fillSmartBlockParentContainer == false %}
			max-width: {{ email_width }}px;
            {%endif %}
width: 100%;

	}

	/* Fancy Headline Styles - Solid Green Color */
	.{{safeid}}__headline-wrapper {
		cursor: default;
		pointer-events: auto;
		text-align: center;
		margin-bottom: 20px;
		position: relative;
		padding-bottom: 15px;
		margin-top: {{ fields.headline.topMargin.size }}{{ fields.headline.topMargin.unit }};
		margin-bottom: {{ fields.headline.bottomMargin.size }}{{ fields.headline.bottomMargin.unit }};
	}

	.{{safeid}}__headline-link {
		display: inline-block;
		text-decoration: none;
		color: inherit;
		cursor: pointer;
	}


	.{{safeid}}__headline-text {
		display: inline-block;
		font-family: gelica, Gelica, Georgia, "Times New Roman", serif !important;
		font-size: 22px;
		font-weight: 700;
		color: #444444;
		letter-spacing: -0.6px;
		line-height: 1.3;
		position: relative;
		z-index: 2;
		margin-top: 10px;
	}

	/* Shop By Category — same Gelica headline as this SmartBlock */
	body > main > div.frontpage > div.category-promotion-wrapper > h2,
	body main div.frontpage div.category-promotion-wrapper > h2,
	.frontpage .category-promotion-wrapper > h2 {
		font-family: gelica, Gelica, Georgia, "Times New Roman", serif !important;
		font-size: 22px !important;
		font-weight: 700 !important;
		color: #444444 !important;
		letter-spacing: -0.6px !important;
		line-height: 1.3 !important;
		text-align: center !important;
	}

	.{{safeid}}__headline-underline {
		position: absolute;
		bottom: 0;
		left: 50%;
		transform: translateX(-50%);
		width: 140px;
		height: 3px;
		background: linear-gradient(90deg, transparent 0%, {{ yougardenBlue }} 30%, {{ yougardenBlueDark }} 50%, {{ yougardenBlue }} 70%, transparent 100%);
		border-radius: 2px;
		box-shadow: 0 1px 4px rgba(38, 79, 28, 0.2);
		animation: underline-pulse 2s ease-in-out infinite;
	}

	@keyframes underline-pulse {
		0%, 100% {
			opacity: 1;
			width: 140px;
			box-shadow: 0 1px 4px rgba(38, 79, 28, 0.2);
		}
		50% {
			opacity: 0.8;
			width: 160px;
			box-shadow: 0 2px 8px rgba(38, 79, 28, 0.4);
		}
	}

	@keyframes underline-glow {
		0%, 100% {
			box-shadow: 0 1px 4px rgba(38, 79, 28, 0.2);
		}
		50% {
			box-shadow: 0 2px 12px rgba(38, 79, 28, 0.5);
		}
	}

	.{{safeid}}__sub-headline {
		cursor: default;
		pointer-events: auto;
