(function() {
    var $slick;

    function initSlick() {
        $slick = $('.{{safeid}}__slick');
        if ($slick.hasClass('slick-initialized')) return;

        var prevArrow = '<button type="button" class="slick-prev slick-arrow" aria-label="Previous Slide"><svg class="svg-inline--fa fa-chevron-left fa-w-10" aria-hidden="true" focusable="false" data-prefix="fas" data-icon="chevron-left" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 512"><path fill="currentColor" d="M34.52 239.03L228.87 44.69c9.37-9.37 24.57-9.37 33.94 0l22.67 22.67c9.36 9.36 9.37 24.52.04 33.9L131.49 256l154.02 154.75c9.34 9.38 9.32 24.54-.04 33.9l-22.67 22.67c-9.37 9.37-24.57 9.37-33.94 0L34.52 272.97c-9.37-9.37-9.37-24.57 0-33.94z"></path></svg></button>';
        var nextArrow = '<button type="button" class="slick-next slick-arrow" aria-label="Next Slide"><svg class="svg-inline--fa fa-chevron-right fa-w-10" aria-hidden="true" focusable="false" data-prefix="fas" data-icon="chevron-right" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 512"><path fill="currentColor" d="M285.476 272.971L91.132 467.314c-9.373 9.373-24.569 9.373-33.941 0l-22.667-22.667c-9.357-9.357-9.375-24.522-.04-33.901L188.505 256 34.484 101.255c-9.335-9.379-9.317-24.544.04-33.901l22.667-22.667c9.373-9.373 24.569-9.373 33.941 0L285.475 239.03c9.373 9.372 9.373 24.568.001 33.941z"></path></svg></button>';
        var arrowOn = {% if show_arrows %}true{% else %}false{% endif %};

        $slick.slick({
            mobileFirst: true,
            slidesToShow: 2,
            slidesToScroll: 2,
            swipeToSlide: false,
            swipe: true,
            touchMove: true,
            draggable: true,
            touchThreshold: 5,
            waitForAnimate: false,
            speed: 400,
            cssEase: 'ease-out',
            /* Same overlay chevrons as category 8-up cards */
            arrows: arrowOn,
            dots: {{ fields.carouselPagination.active }},
            prevArrow: prevArrow,
            nextArrow: nextArrow,
            autoplay: true,
            autoplaySpeed: 8000,
            infinite: {{ fields.carouselActive.loop }},
            responsive: [
                {
                    breakpoint: 480,
                    settings: { slidesToShow: 3, slidesToScroll: 3, arrows: arrowOn }
                },
                {
                    breakpoint: 1024,
                    settings: { slidesToShow: 4, slidesToScroll: 4, arrows: arrowOn }
                },
                {
                    breakpoint: 1280,
                    settings: { slidesToShow: {{ fields.columns }}, slidesToScroll: {{ fields.columns }}, arrows: arrowOn }
                }
            ]
        });

        function syncPageScroll() {
            if (!$slick.hasClass('slick-initialized')) return;
            var show = parseInt($slick.slick('slickGetOption', 'slidesToShow'), 10) || 2;
            var scroll = parseInt($slick.slick('slickGetOption', 'slidesToScroll'), 10) || 1;
            if (scroll !== show) {
                $slick.slick('slickSetOption', 'slidesToScroll', show, true);
            }
        }
        syncPageScroll();
        $slick.on('breakpoint reInit', syncPageScroll);
        $slick.on('click', '.slick-next, .slick-prev', function(e) {
            if (this && this.blur) this.blur();
            var show = parseInt($slick.slick('slickGetOption', 'slidesToShow'), 10) || 2;
            var scroll = parseInt($slick.slick('slickGetOption', 'slidesToScroll'), 10) || 1;
            if (scroll !== show) {
                e.preventDefault();
                e.stopImmediatePropagation();
                var dir = $(this).hasClass('slick-next') ? show : -show;
                var current = parseInt($slick.slick('slickCurrentSlide'), 10) || 0;
                $slick.slick('slickGoTo', current + dir);
                return false;
            }
        });
        $slick.on('mouseleave', function() {
            $slick.find('.slick-arrow').each(function() {
                if (this.blur) this.blur();
            });
        });

        if (arrowOn) {
            setTimeout(function() {
                centerHomeArrows();
                $slick.on('setPosition afterChange breakpoint reInit', centerHomeArrows);
                jQuery(window).on('resize', centerHomeArrows);
            }, 100);
        }
    }

    function hideExtraArrows(root) {
        function pick(cls) {
            var direct = root.querySelector(':scope > .' + cls);
            var nodes = root.querySelectorAll('.' + cls);
            var keep = direct || nodes[nodes.length - 1] || nodes[0] || null;
            var i;
            for (i = 0; i < nodes.length; i++) {
                if (nodes[i] === keep) continue;
                nodes[i].style.setProperty('display', 'none', 'important');
                nodes[i].style.setProperty('visibility', 'hidden', 'important');
                nodes[i].style.setProperty('pointer-events', 'none', 'important');
            }
        }
        pick('slick-prev');
        pick('slick-next');
    }

    function centerHomeArrows() {
        if (!$slick || !$slick.length) return;
        var el = $slick.get(0);
        if (!el) return;
        hideExtraArrows(el);

        /* Vertical only — left/right stay 8px like the category tiles.
           Never key off the current slide: that made arrows jump inward on click. */
        var img = el.querySelector('.slick-list .slick-slide.slick-active .{{safeid}}__product-image img')
            || el.querySelector('.slick-list .{{safeid}}__product-image img')
            || el.querySelector('.slick-list img');
        var top = 80;
        if (img) {
            var cr = el.getBoundingClientRect();
            var ir = img.getBoundingClientRect();
            if (ir.height) top = Math.round((ir.top - cr.top) + (ir.height / 2));
        }
        el.style.setProperty('--yg-home-arrow-top', top + 'px');
        el.classList.add('yg-home-arrows-ready');
    }

    if (typeof jQuery !== "undefined") {
        jQuery(document).ready(initSlick);
    } else {
        document.addEventListener("DOMContentLoaded", function() {
            if (typeof jQuery !== "undefined") initSlick();
        });
    }
})();
