    window.addEventListener('resize', centerArrows);
    document.addEventListener('click', function (e) {
      var btn = e.target && e.target.closest ? e.target.closest(SEL + ' .slick-arrow') : null;
      if (btn && btn.blur) btn.blur();
    });
    if (window.jQuery) {
      window.jQuery(SEL).on('setPosition afterChange breakpoint reInit', centerArrows);
      window.jQuery(SEL).on('mouseleave', function () {
        window.jQuery(this).find('.slick-arrow').each(function () {
          if (this.blur) this.blur();
        });
      });
    }
    var started = Date.now();
    (function tick() {
      centerArrows();
      if (Date.now() - started < 10000) setTimeout(tick, 150);
    })();
  }

  boot();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  }
  window.requestAnimationFrame(centerArrows);
})();
